struct Point3D { float x, y, z; };
struct BoundingBox3D { Point3D Min; Point3D Max; };

bool AreBoxesOverlapped(const BoundingBox3D& a, const BoundingBox3D& b) {
    return (a.Min.x <= b.Max.x && a.Max.x >= b.Min.x) &&
           (a.Min.y <= b.Max.y && a.Max.y >= b.Min.y) &&
           (a.Min.z <= b.Max.z && a.Max.z >= b.Min.z);
}

std::vector<std::pair<size_t, size_t>> CollisionDetectionSimplified(const std::vector<BoundingBox3D>& boxes) {
    std::vector<std::pair<size_t, size_t>> collisions;

    for (size_t i = 0; i < boxes.size(); ++i) {
        for (size_t j = i + 1; j < boxes.size(); ++j) {
            if (AreBoxesOverlapped(boxes[i], boxes[j])) {
                collisions.emplace_back(i, j);
            }
        }
    }

    return collisions;
}

int main() {
    std::vector<BoundingBox3D> boxes = {
        {{0,0,0}, {1,1,1}},
        {{0.5,0.5,0.5}, {1.5,1.5,1.5}},
        {{2,2,2}, {3,3,3}}
    };

    auto result = CollisionDetectionSimplified(boxes);
    return result.size() == 1 ? 0 : 1;
}

